INSERT INTO `happy_customers` VALUES 
('1', 'Mahade Hasan', 'মাহাদি হাসান', '4', 'I found everything I needed in one place. Highly recommend this store!', 'এক জায়গায় প্রয়োজনীয় সব পেয়েছি। এই শপটি অবশ্যই শেয়ার করার মতো!', '1', '2026-09-24 12:37:00'),
('2', 'Sabbir Hossain', 'সাব্বির হোসাইন', '5', 'Good packaging, nothing was damaged. The delivery guy was very polite.', 'ভালো প্যাকেজিং, কোনো কিছুই নষ্ট হয়নি। ডেলিভারি ম্যান খুব ভদ্র ছিলেন।', '1', '2026-09-24 12:37:00'),
('3', 'Towfiq Omar', 'তৌফিক ওমর', '5', 'Bazar.com makes my weekly grocery shopping so much easier and faster.', 'Bazar.com আমার সাপ্তাহিক মুদি কেনাকাটা অনেক সহজ ও দ্রুত করে দিয়েছে।', '1', '2026-09-24 12:37:00'),
('4', 'Mahatab Hossain', 'মাহাতাব হোসাইন', '4', 'I love the variety of products available. The prices are also very reasonable.', 'এখানে প্রচুর বৈচিত্র্যময় পণ্য পাওয়া যায়। দামও অনেক যুক্তিসঙ্গত।', '1', '2026-09-24 12:37:00'),
('5', 'Kamrul Hasan', 'কামরুল হাসান', '5', 'The vegetables were incredibly fresh. Excellent service all around.', 'সবজিগুলো খুবই সতেজ ছিল। সবমিলিয়ে দুর্দান্ত সার্ভিস।', '1', '2026-09-24 12:37:00'),
('6', 'Dipto Chowdhury', 'দীপ্ত চৌধুরী', '5', 'Great quality products and fast delivery! Will definitely order again.', 'চমৎকার মানের পণ্য এবং দ্রুত ডেলিভারি! নিশ্চিতভাবেই আবার অর্ডার করব।', '1', '2026-09-24 12:37:00');
