('1', 'PRD-00001', NULL, '16', 'Fresh Red Tomato', 'তাজা পাকা টমেটো', NULL, 'Naturally ripened, fresh red tomatoes rich in nutrients.', 'গাছে পাকা সুস্বাদু ও পুষ্টিকর লাল টমেটো।', '1 kg', '১ কেজি', 'kg', '60.00', '75.00', '20', 'https://images.unsplash.com/photo-1592924357228-91a4daadcfea?w=500', '100', '1', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('2', 'PRD-00002', NULL, '16', 'Deshi Potato (Alu)', 'দেশি নতুন আলু', NULL, 'Premium quality fresh clean round potatoes.', 'পরিষ্কার ও স্বাস্থ্যসম্মত টাটকা গোল আলু।', '1 kg', '১ কেজি', 'kg', '40.00', '45.00', '11', 'https://images.unsplash.com/photo-1518977676601-b53f82aba655?w=500', '150', '1', '0', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('3', 'PRD-00003', NULL, '16', 'Fresh Onion (Peyaj)', 'দেশি লাল পেঁয়াজ', NULL, 'Best quality pungent dry deshi onions.', 'রান্নার অপরিহার্য খাঁটি দেশি লাল পেঁয়াজ।', '1 kg', '১ কেজি', 'kg', '95.00', '110.00', '14', 'https://images.unsplash.com/photo-1618512496248-a07fe83aa8cb?w=500', '120', '1', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('4', 'PRD-00004', NULL, '16', 'Green Chilli (Kacha Morich)', 'তাজা কাঁচা মরিচ', NULL, 'Fresh spicy green chillies direct from farm.', 'ঝাল ও ফ্রেশ কাঁচা মরিচ।', '250 gm', '২৫০ গ্রাম', 'kg', '35.00', '45.00', '22', 'https://images.unsplash.com/photo-1588252303782-cb80119abd6d?w=500', '170', '0', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('5', 'PRD-00005', NULL, '9', 'River Rui Fish', 'নদীর তাজা রুই মাছ', NULL, 'Fresh sweet river Rui fish, cleaned and scaled.', 'নদীর তাজা ও সুস্বাদু রুই মাছ (কাটা ও পরিষ্কার)।', '1.5 kg', '১.৫ কেজি', 'kg', '480.00', '550.00', '13', 'https://images.unsplash.com/photo-1534043464124-3be32fe000c9?w=500', '20', '1', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('6', 'PRD-00006', NULL, '9', 'Chittagong Hilsha Fish', 'পদ্মার তাজা রূপালী ইলিশ', NULL, 'Authentic Padma river silver Hilsha fish with rich aroma.', 'স্বাদে ও গন্ধে অতুলনীয় পদ্মার রূপালী ইলিশ।', '1 kg (Size 1kg+)', '১ কেজি (১ কেজি+ সাইজ)', 'kg', '1450.00', '1650.00', '12', 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?w=500', '20', '1', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('7', 'PRD-00007', NULL, '3', 'Premium Beef (Bone-in)', 'গরুর খাঁটি মাংস (হাড় সহ)', NULL, '100% Halal and fresh local farm beef.', '১০০% হালাল ও টাটকা কচি গরুর মাংস।', '1 kg', '১ কেজি', 'kg', '750.00', '800.00', '6', 'https://images.unsplash.com/photo-1603048588665-791ca8aea617?w=500', '40', '1', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('8', 'PRD-00008', NULL, '3', 'Broiler Chicken (Dressed)', 'ব্রয়লার মুরগি (চামড়া ছাড়া)', NULL, 'Hygienically dressed and thoroughly cleaned fresh chicken.', 'স্বাস্থ্যসম্মতভাবে ড্রেসিং ও পরিষ্কার করা তাজা মুরগি।', '1 kg', '১ কেজি', 'kg', '190.00', '210.00', '10', 'https://images.unsplash.com/photo-1604503468506-a8da13d82791?w=500', '50', '1', '0', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('9', 'PRD-00009', NULL, '4', 'Premium Miniket Rice', 'মিনিকেট প্রিমিয়াম চাল', NULL, 'Long grain, polished and fragrant Miniket rice.', 'ঝরঝরে ও সুস্বাদু প্রিমিয়াম মিনিকেট চাল।', '5 kg Bag', '৫ কেজি ব্যাগ', 'kg', '390.00', '425.00', '8', 'https://images.unsplash.com/photo-1586201375761-83865001e31c?w=500', '60', '1', '0', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('10', 'PRD-00010', NULL, '4', 'Deshi Mosur Dal', 'দেশি চিকন মসুর ডাল', NULL, 'Small grain pure organic deshi red lentils.', 'দ্রুত সিদ্ধ হওয়া খাঁটি দেশি ছোট দানার মসুর ডাল।', '1 kg', '১ কেজি', 'kg', '140.00', '155.00', '10', 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=500', '70', '0', '0', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('11', 'PRD-00011', NULL, '13', 'Rupchanda Fortified Soyabean Oil', 'রূপচাঁদা ফর্টিফাইড সয়াবিন তেল', NULL, 'Enriched with Vitamin A and D, heart friendly.', 'ভিটামিন এ ও ডি সমৃদ্ধ স্বাস্থ্যসম্মত সয়াবিন তেল।', '5 Liter', '৫ লিটার', 'kg', '890.00', '950.00', '6', 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=500', '45', '1', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('12', 'PRD-00012', NULL, '13', 'Radhuni Pure Mustard Oil', 'রাঁধুনী খাঁটি সরিষার তেল', NULL, 'Traditional cold-pressed mustard oil with sharp pungent flavor.', 'খাঁটি ঝাঁঝালো ঘানিতে ভাঙা সরিষার তেল।', '1 Liter', '১ লিটার', 'kg', '290.00', '320.00', '9', 'https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=500', '35', '0', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('13', 'PRD-00013', NULL, '14', 'Farm Fresh Red Eggs (Dozen)', 'ফার্মের লাল ডিম (১২ টি)', NULL, 'Grade A farm fresh healthy red chicken eggs.', 'পুষ্টিকর ও সতেজ গ্রেড-এ লাল মুরগির ডিম।', '12 Pcs', '১২ টি', 'kg', '145.00', '160.00', '9', 'https://images.unsplash.com/photo-1516448620398-c5f44bf9f441?w=500', '100', '1', '1', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
('14', 'PRD-00014', NULL, '14', 'Aarong Dairy Pasteurized Milk', 'আড়ং ডেইরি পাস্তুরিত তরল দুধ', NULL, '100% pure fresh cow milk.', 'খাঁটি গরুর স্বাস্থ্যকর তরল দুধ।', '1 Liter', '১ লিটার', 'kg', '90.00', '95.00', '5', 'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=500', '50', '0', '0', '0', 'active', '2026-09-22 10:31:42', '1', '1'),
